CREATE TABLE jurisdictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, type text NOT NULL CHECK (type IN ('COUNTRY','STATE','LGA','WARD')), parent_id uuid REFERENCES jurisdictions(id), official_code text, boundary geometry(MultiPolygon,4326) NOT NULL, source text NOT NULL, source_url text, license text, effective_from date, effective_to date, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jurisdictions_boundary_gist ON jurisdictions USING gist(boundary);
CREATE TABLE organization_jurisdictions (organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, jurisdiction_id uuid NOT NULL REFERENCES jurisdictions(id) ON DELETE CASCADE, PRIMARY KEY (organization_id,jurisdiction_id));
CREATE TABLE assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, asset_type text NOT NULL, geometry geometry(Geometry,4326), jurisdiction_id uuid REFERENCES jurisdictions(id), owner_organization_id uuid REFERENCES organizations(id), managing_organization_id uuid REFERENCES organizations(id), regulatory_organization_id uuid REFERENCES organizations(id), ownership_level text, source text NOT NULL, source_url text, verified boolean NOT NULL DEFAULT false, public_visibility boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX assets_geometry_gist ON assets USING gist(geometry);
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_user_id uuid NOT NULL REFERENCES users(id), original_text text, location geometry(Point,4326), location_accuracy_meters numeric, location_source text, user_confirmed_location boolean NOT NULL DEFAULT false, typed_location text, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','SUBMITTED','PROCESSING','PROCESSED','NEEDS_REVIEW','FAILED')), visibility text NOT NULL DEFAULT 'PRIVATE', created_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, processed_at timestamptz);
CREATE INDEX reports_location_gist ON reports USING gist(location);
CREATE TABLE report_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, cloudinary_public_id text NOT NULL UNIQUE, cloudinary_asset_id text, resource_type text NOT NULL, format text, bytes bigint, width integer, height integer, duration numeric, mime_type text NOT NULL, visibility text NOT NULL DEFAULT 'RESTRICTED', upload_verified_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE report_analysis (report_id uuid PRIMARY KEY REFERENCES reports(id) ON DELETE CASCADE, detected_language text, language_confidence numeric, original_transcript text, english_transcript text, title text, summary text, full_description text, has_civic_issue boolean, category text, subcategory text, affected_assets jsonb NOT NULL DEFAULT '[]', observations jsonb NOT NULL DEFAULT '[]', urgency_signals jsonb NOT NULL DEFAULT '[]', location_mentions jsonb NOT NULL DEFAULT '[]', model_name text, analysis_version text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_reference text NOT NULL UNIQUE, title text NOT NULL, summary text, category text, subcategory text, location geometry(Point,4326), lga_jurisdiction_id uuid REFERENCES jurisdictions(id), state_jurisdiction_id uuid REFERENCES jurisdictions(id), official_status text NOT NULL DEFAULT 'OPEN', community_verification_status text NOT NULL DEFAULT 'UNVERIFIED', report_count integer NOT NULL DEFAULT 0, public_visibility text NOT NULL DEFAULT 'PUBLIC', first_reported_at timestamptz NOT NULL DEFAULT now(), last_reported_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX incidents_location_gist ON incidents USING gist(location);
CREATE TABLE incident_reports (incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, report_id uuid NOT NULL UNIQUE REFERENCES reports(id) ON DELETE CASCADE, matching_method text NOT NULL, matching_confidence numeric, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(incident_id, report_id));
CREATE TABLE incident_merge_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_incident_id uuid NOT NULL REFERENCES incidents(id), target_incident_id uuid NOT NULL REFERENCES incidents(id), action text NOT NULL CHECK(action IN ('MERGE','SPLIT','MOVE_REPORT')), report_id uuid REFERENCES reports(id), reason text NOT NULL, actor_user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE routing_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, candidate_organization_ids jsonb NOT NULL, selected_organization_ids jsonb NOT NULL, rationale text NOT NULL, primary_confidence numeric, missing_information jsonb NOT NULL DEFAULT '[]', review_required boolean NOT NULL DEFAULT false, model_name text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incident_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES organizations(id), role text NOT NULL CHECK(role IN ('PRIMARY','SUPPORTING')), routing_confidence numeric, routing_reason text, routing_method text NOT NULL CHECK(routing_method IN ('AI','MANUAL')), status text NOT NULL DEFAULT 'ACTIVE', assigned_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewed_by uuid REFERENCES users(id), UNIQUE(incident_id,organization_id));
CREATE TABLE incident_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, author_user_id uuid REFERENCES users(id), author_organization_id uuid REFERENCES organizations(id), type text NOT NULL, body text NOT NULL, visibility text NOT NULL DEFAULT 'PUBLIC', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incident_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, from_status text, to_status text NOT NULL, changed_by_user_id uuid REFERENCES users(id), organization_id uuid REFERENCES organizations(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
